import React, { ReactNode } from 'react';
import { Text } from '@fiverr-private/typography';
import { type Types } from '@fiverr-private/theme';
import { FORM_SUBTITLE_ID } from '../../constants';

interface FormSubtitleProps extends Pick<Types.BoxType, 'dataTrackTag' | 'dataTrackValue'> {
  children: ReactNode;
}

export const FormSubtitle = ({ children, dataTrackTag = 'form_subtitle', dataTrackValue }: FormSubtitleProps) => (
  <Text dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue} size="b_sm" color="bodySecondary">
    {children}
  </Text>
);

FormSubtitle.id = FORM_SUBTITLE_ID;
FormSubtitle.displayName = FORM_SUBTITLE_ID;

export default FormSubtitle;
