import React from 'react';
import { Counter } from '@fiverr-private/data_display';
import { I18n } from '@fiverr-private/i18n-react';
import { Typography } from '@fiverr-private/typography';
import { useInputTrackValue } from '@fiverr-private/inputs';
import { FormCounterProps } from '../types';
import { useFormContext } from '../FormContext';
import { FORM_COUNTER_ID } from '../constants';

const FormCounter = ({
  maxLength,
  value = '',
  format,
  dataTrackTag = 'form_counter',
  dataTrackValue,
}: FormCounterProps) => {
  const { value: formValue, maxLength: formMaxLength } = useFormContext();
  const stringValueLength = (formValue || value)?.toString().length;
  const trackValue = useInputTrackValue({ dataTrackValue, value: stringValueLength });
  const currentMaxLength = formMaxLength || maxLength;
  const i18nProps = currentMaxLength
    ? { k: 'forms.formCounter.characters.other' }
    : { k: 'forms.formCounter.characters', params: { count: stringValueLength } };
  return (
    <Typography dataTrackTag={dataTrackTag} dataTrackValue={trackValue} as="span" marginLeft="auto">
      <Counter current={stringValueLength} max={currentMaxLength} format={format} />
      &nbsp;
      <I18n {...i18nProps} />
    </Typography>
  );
};

FormCounter.id = FORM_COUNTER_ID;
FormCounter.displayName = FORM_COUNTER_ID;

export default FormCounter;
